import pandas as pd
import re
from datetime import datetime

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    raw = inputs["raw_payments"].copy()

    # Initialize reject tracking
    rejects = []
    valid_rows = []

    for idx, row in raw.iterrows():
        row_num = row["row_num"]
        payment_id = row["payment_id"]
        account_id = row["account_id"]
        amount_txt = row["amount_txt"]
        currency = row["currency"]
        pay_date_txt = row["pay_date_txt"]

        reject_reason = None

        # R1: MISSING_ID
        if reject_reason is None:
            if pd.isna(payment_id) or (isinstance(payment_id, str) and payment_id.strip() == ""):
                reject_reason = "MISSING_ID"

        # R2: BAD_AMOUNT
        if reject_reason is None:
            if pd.isna(amount_txt):
                reject_reason = "BAD_AMOUNT"
            else:
                amount_str = amount_txt.strip()
                # Legacy number: optional +/-, one or more digits, optional .DD
                pattern = r'^[+-]?\d+(\.\d{1,2})?$'
                if not re.match(pattern, amount_str):
                    reject_reason = "BAD_AMOUNT"

        # R3: NON_POSITIVE
        if reject_reason is None:
            try:
                amount_val = float(amount_str)
                if amount_val <= 0:
                    reject_reason = "NON_POSITIVE"
            except:
                reject_reason = "BAD_AMOUNT"

        # R4: BAD_CURRENCY
        if reject_reason is None:
            if pd.isna(currency):
                reject_reason = "BAD_CURRENCY"
            else:
                currency_upper = currency.strip().upper()
                if currency_upper not in ["USD", "EUR", "GBP"]:
                    reject_reason = "BAD_CURRENCY"

        # R5: BAD_DATE
        if reject_reason is None:
            if pd.isna(pay_date_txt):
                reject_reason = "BAD_DATE"
            else:
                date_str = pay_date_txt.strip()
                # Check format YYYY-MM-DD
                if not re.match(r'^\d{4}-\d{2}-\d{2}$', date_str):
                    reject_reason = "BAD_DATE"
                else:
                    try:
                        parsed_date = datetime.strptime(date_str, "%Y-%m-%d")
                    except ValueError:
                        reject_reason = "BAD_DATE"

        if reject_reason is not None:
            rejects.append({"row_num": row_num, "reject_reason": reject_reason})
        else:
            # Row passed R1-R5, store for duplicate check
            valid_rows.append({
                "row_num": row_num,
                "payment_id": payment_id.strip(),
                "account_id": account_id,
                "amount": float(amount_str),
                "currency": currency_upper,
                "pay_date": datetime.strptime(date_str, "%Y-%m-%d").date(),
                "original_row": row
            })

    # R6: DUPLICATE - among valid rows, keep only the one with lowest row_num per payment_id
    if valid_rows:
        valid_df_temp = pd.DataFrame(valid_rows)
        # Group by payment_id and find the minimum row_num in each group
        min_row_per_id = valid_df_temp.groupby("payment_id")["row_num"].min()

        for _, v_row in valid_df_temp.iterrows():
            if v_row["row_num"] == min_row_per_id[v_row["payment_id"]]:
                # This is the keeper row
                pass
            else:
                # This is a duplicate
                rejects.append({
                    "row_num": v_row["row_num"],
                    "reject_reason": "DUPLICATE"
                })

        # Build final valid_payments from rows that weren't rejected as duplicates
        final_valid = []
        for _, v_row in valid_df_temp.iterrows():
            if v_row["row_num"] == min_row_per_id[v_row["payment_id"]]:
                final_valid.append({
                    "payment_id": v_row["payment_id"],
                    "account_id": v_row["account_id"],
                    "amount": v_row["amount"],
                    "currency": v_row["currency"],
                    "pay_date": v_row["pay_date"]
                })

        valid_payments = pd.DataFrame(final_valid)
    else:
        valid_payments = pd.DataFrame(columns=["payment_id", "account_id", "amount", "currency", "pay_date"])

    payment_rejects = pd.DataFrame(rejects)

    # Ensure correct dtypes
    if len(valid_payments) == 0:
        valid_payments = pd.DataFrame(columns=["payment_id", "account_id", "amount", "currency", "pay_date"])
        valid_payments = valid_payments.astype({
            "payment_id": "object",
            "account_id": "int64",
            "amount": "float64",
            "currency": "object",
            "pay_date": "object"
        })
    else:
        valid_payments["account_id"] = valid_payments["account_id"].astype("int64")
        valid_payments["amount"] = valid_payments["amount"].astype("float64")

    if len(payment_rejects) == 0:
        payment_rejects = pd.DataFrame(columns=["row_num", "reject_reason"])
        payment_rejects = payment_rejects.astype({
            "row_num": "int64",
            "reject_reason": "object"
        })
    else:
        payment_rejects["row_num"] = payment_rejects["row_num"].astype("int64")

    return {
        "valid_payments": valid_payments,
        "payment_rejects": payment_rejects
    }
